import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CKEOJfYu.js";var i=JSON.parse(`{"title":"The End dragon fight","description":"","frontmatter":{"title":"The End dragon fight","group":"Documents","category":"Guides","head":[["meta",{"property":"og:title","content":"The End dragon fight"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/data-driven/end-fight"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/data-driven/end-fight"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/data-driven/end-fight.md"}},"headers":[],"relativePath":"data-driven/end-fight.md","filePath":"data-driven/end-fight.md","lastUpdated":1793446181000}`),a={name:`data-driven/end-fight.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="the-end-dragon-fight" tabindex="-1">The End dragon fight <a class="header-anchor" href="#the-end-dragon-fight" aria-label="Permalink to “The End dragon fight”">​</a></h1><p>The End fight is managed by each End world&#39;s <code>DragonFight</code> service. When a player enters the arena around (0, 128, 0), the service checks for the exit podium, creates it if needed, and spawns the dragon if the world has not recorded a kill. The End&#39;s generated spike pillars and crystals are part of the arena, and the server sends a boss bar while the player is nearby.</p><p>When the dragon dies, the server opens the podium&#39;s portal, places a gateway block, and drops the dragon egg on the world&#39;s first kill. It pays the first-kill experience and hides the boss bar. Entering the exit portal starts credits on a player&#39;s first exit from that save. The transfer to the player&#39;s respawn point waits for the client to finish or skip the credits. Later exits skip the credits screen.</p><h2 id="respawning-the-dragon" tabindex="-1">Respawning the dragon <a class="header-anchor" href="#respawning-the-dragon" aria-label="Permalink to “Respawning the dragon”">​</a></h2><p>Place four end crystals on obsidian or bedrock at the four cardinal positions, three blocks from the exit portal&#39;s center. The block above each base must be air, and the crystal&#39;s spawn volume must be clear of entities. A valid arrangement starts the saved respawn sequence: the crystals beam toward the center, each of the ten pillars resets over 40 ticks, and the dragon is summoned after the final 100-tick phase. The full sequence takes 601 game ticks. Destroying a driving crystal aborts the sequence and restores the active exit podium. A reload resumes only while all four saved crystals are present.</p><p>The gateway block is placed at dragon death, but stepping into a gateway does not teleport yet.</p><h2 id="light-in-the-end-and-nether" tabindex="-1">Light in the End and Nether <a class="header-anchor" href="#light-in-the-end-and-nether" aria-label="Permalink to “Light in the End and Nether”">​</a></h2><p>Gameplay rules read a dimension-aware <code>blocks.light</code> value: the maximum of block light, dimension-scaled sky light, and ambient light. Vanilla End ambient light gives a minimum value of 3; Nether ambient light gives a minimum of 1. This fixes server-side light checks for behaviors such as spawning and growth. Bedrock packets do not carry light arrays, so this does not change the client&#39;s rendered brightness.</p><p>See <a href="/JSPrismarine/pr-preview/pr-2977/data-driven/dimensions.html">dimensions.md</a> for portal travel and dimension configuration, and <a href="/JSPrismarine/pr-preview/pr-2977/data-driven/engine-systems.html#light">engine-systems.md</a> for the light engine.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};